package rikka.shizuku;import android.content.*;import android.os.*;import java.util.*;import com.igareck.antidpi.FakeTransport;public class Shizuku {public static volatile FakeTransport target=new FakeTransport();public static volatile boolean available=true,failNext,suppressNext;public static int binds,removes,detaches;public static final List<ServiceConnection> connections=new ArrayList<>();public static class UserServiceArgs {public UserServiceArgs(ComponentName n){}public UserServiceArgs daemon(boolean b){return this;}public UserServiceArgs processNameSuffix(String s){return this;}public UserServiceArgs version(int n){return this;}}public static boolean pingBinder(){return available;}public static int checkSelfPermission(){return 0;}public static void requestPermission(int n){}public static void bindUserService(UserServiceArgs a,ServiceConnection c){binds++;if(failNext){failNext=false;throw new IllegalStateException("injected bind failure");}connections.add(c);if(suppressNext){suppressNext=false;return;}c.onServiceConnected(null,target);}public static void unbindUserService(UserServiceArgs a,ServiceConnection c,boolean remove){connections.remove(c);if(remove){removes++;target.die();c.onServiceDisconnected(null);}else detaches++;}public static void disconnect(){for(ServiceConnection c:new ArrayList<>(connections))c.onServiceDisconnected(null);} }
